function questionPool(ep,type,settings){
 const pack=BANKS[String(ep.id)];
 if(!pack)return null;
 if(!['mc','tf','fill','short'].includes(type))return [];
 return pack.questions.map((f,i)=>{
  const choice=f.wrongs[rand(f.wrongs.length)];
  const question={id:`${ep.id}-bank-${type}-${i}-${rand(1000000)}`,fact:i,type,mode:f.mode,difficulty:f.difficulty,points:type==='short'?3:1,prompt:'',answer:'',options:null};
  if(type==='mc'){
   question.prompt=f.question;question.answer=f.answer;question.options=shuffle([f.answer,...f.wrongs]);
  }else if(type==='tf'){
   const valid=rand(2)===1;
   if(f.tfNegation){const correct=f.fill.replace('{blank}',f.answer).replace(/[.!?]*$/,'');let falseVersion=correct[0].toLowerCase()+correct.slice(1);question.prompt='True or false: '+(valid?correct:'It is not true that '+falseVersion)+'.';}
   else question.prompt='True or false: '+f.fill.replace('{blank}',valid?f.answer:choice).replace(/[.!?]*$/,'')+'.';
   question.answer=valid?'True':'False';question.explanation=valid?'The statement is correct.':`The correct information is: ${f.fill.replace('{blank}',f.answer)}`;
  }else if(type==='fill'){question.prompt=f.fill.replace('{blank}','__________________');question.answer=f.answer;}
  else{question.prompt=f.question;question.answer=f.fill.replace('{blank}',f.answer);}
  return question;
 });
}

let selected=EPISODES[0], mode='watch', worksheet=[], saved={}, exactMode=false, currentEdit=-1, teacherAnswers=false, unsavedChanges=false;
