$('#count').addEventListener('input',e=>{$('#countDisplay').textContent=e.target.value;updateExact()});
$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));
$('#toggleCounts').onclick=()=>{exactMode=!exactMode;$('#exactCounts').classList.toggle('hidden',!exactMode);$('#countChevron').textContent=exactMode?'⌃':'⌄'};
$('#generateBtn').onclick=generate;$('#regenerateAll').onclick=generate;$('#addQuestion').onclick=addQuestion;$('#saveBtn').onclick=saveAssignment;$('#savedBtn').onclick=showSaved;$('#helpBtn').onclick=help;$('#videoLibraryBtn').onclick=()=>openVideoLibrary();$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#docxBtn').onclick=()=>exportFiles('docx');$('#pdfBtn').onclick=()=>exportFiles('pdf');
setMode('watch');renderHero();createTypes();episodeRender();renderPreview();persist();
